  "tests": [
    { "name": "Api.login",         "status": "passed",  "duration": 0.32 },
    { "name": "Api.logout",        "status": "passed",  "duration": 0.11 },
    { "name": "Api.brokenFeature", "status": "failed",  "duration": 0.04 },
    { "name": "Api.timeout",       "status": "skipped", "duration": 0.00 }
